function showAquatic(route='center',message=''){const v=aquaticView(state.aquatic,route,state.construction.kits);open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=aquaticArt(v.art);const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const a of v.actions)button(a.label,()=>{const r=aquaticAction(state.aquatic,a,state.construction.kits);state.aquatic=r.aquatic;persist();if(r.travel){close();select(objects.find(o=>o.id===r.travel));return}if(r.reset){state.path=[];state.pending=null;state.x=180;state.y=460;renderTargets();}if(r.resume){close();renderTargets();announce(r.message);return;}showAquatic(r.route,r.message)},choices);button('🔊 Listen',()=>readJournal(v.text));button('🌊 Explore',()=>{close();renderTargets();});paragraph(message||'Protected learning models. No animals captured; no oxygen or damage timer.');}
const swimImages=new Map();function swimImage(key,svg){if(!swimImages.has(key)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);swimImages.set(key,img);}return swimImages.get(key);}
function drawSwimmingLife(){const phase=state.swimPhase||0;for(const [i,o]of activeObjects().entries()){if(!o.life&&!o.find)continue;const key=o.life?'life-'+o.life:'find-'+o.find,img=swimImage(key,o.life?swimLifeSvg(o.life):swimFindSvg(o.find));const bob=o.life?swimOffset(i,phase,state.settings.reduced):0;if(img.complete&&img.naturalWidth)ctx.drawImage(img,o.x-50,o.y-40+bob,100,80);if((o.life?state.aquatic.observed:state.aquatic.samples).includes(o.life||o.find)){ctx.fillStyle='#fffbed';ctx.fillRect(o.x+28,o.y-39,22,22);ctx.fillStyle='#17384a';ctx.font='bold 19px system-ui';ctx.fillText('✓',o.x+29,o.y-21);}}if(state.settings.effects&&!state.settings.reduced){ctx.strokeStyle='#a6e0df88';ctx.lineWidth=2;for(let i=0;i<8;i++){const x=100+i*110,y=470-((phase*15+i*43)%280);ctx.beginPath();ctx.arc(x,y,3+i%3,0,Math.PI*2);ctx.stroke();}}}
