function refreshConstructionControls(){if(typeof buildControls==='undefined')return;renderConstructionControls({root:buildControls,state:state.construction,onCell:(x,y)=>{if(state.paused){announce('Tap Resume to keep building.');return}if(placeBuild(state.construction,x,y)){persist();refreshConstructionControls();chime();announce('Prefab placed or changed.')}},onPart:id=>{state.construction.selected=id;refreshConstructionControls();announce('Selected '+id);},onAction:constructionControl});}
function constructionControl(action){const c=state.construction;if(action==='exit'){const wasOrbit=c.orbit;c.active=null;c.orbit=false;if(wasOrbit)changeZone('grounds');else renderTargets();return}if(action==='listen'){readJournal('Training orbital preview. The planets move around a star. Our station is the foreground viewpoint. This is not a generated solar system yet.');return}if(state.paused){announce('Tap Resume to keep building.');return}if(action==='parts'){showConstruction('parts');return}if(action==='test'){const r=testBuild(c);persist();open('Model test');paragraph(constructionResult(r),'journal-intro');button('← Keep building',close);button('📦 My construction parts',()=>showConstruction('parts'));button('🔊 Listen',()=>readJournal(constructionResult(r)));return}if(action==='rotate')c.rotation=(c.rotation+1)%4;else buildAction(c,action);persist();refreshConstructionControls();announce(action==='robot'?'Robot demonstrated the plan. Tap Test to inspect it.':'Construction model updated.');}
function showConstruction(page='projects'){if(page==='rocket'){const result=machineCommand(state.machines,{type:'blueprint',value:'rocket'});state.machines=result.machines;persist();showMachines(result.route);return}const c=state.construction,v=constructionView(c,page);open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=constructionArt(v.art);const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const a of v.actions)button(a.label,()=>{if(a.type==='resume'){close();return}if(a.type==='demonstrate'){if(c.active)buildAction(c,'robot');persist();refreshConstructionControls();close();return}if(a.type==='home'){close();select(objects.find(o=>o.id==='grounds-home'));return}if(a.type==='build'){openBuild(c,a.value);close();persist();renderTargets();return}if(a.type==='fit'){if(!c.kits.includes(a.value))return;if(!state.farm.constructionModules.includes(a.value))state.farm.constructionModules.push(a.value);if(!c.modules.includes(a.value))c.modules.push(a.value);c.active=null;c.orbit=false;persist();close();select(objects.find(o=>o.id==='farm-robot'));return}const next=constructionDispatch(c,a);persist();if(c.orbit){c.active=null;close();renderTargets();announce('Training orbital preview unlocked.');}else showConstruction(next)},choices);button('🔊 Listen',()=>readJournal(v.text));}
const buildImages=new Map();function tileImage(part,rotation){const key=part+'-'+rotation;if(!buildImages.has(key)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(constructionCellSvg(part,rotation));buildImages.set(key,img)}return buildImages.get(key);}
function drawConstruction(t){const c=state.construction;rect(0,0,1000,600,'#203c4b');ctx.fillStyle='#eff8f5';ctx.font='bold 24px system-ui';ctx.fillText(constructionProjects[c.active].name,35,65);const hints=new Map(constructionProjects[c.active].solution.map(([x,y,p,r])=>[y*12+x,{part:p,rotation:r}]));for(let y=0;y<5;y++)for(let x=0;x<12;x++){const fixed=buildFixed(c.active,x,y),placed=c.boards[c.active][y*12+x],hint=c.hints?hints.get(y*12+x):null;const cell=fixed?(c.active==='power'&&x===11?{part:y===2?'wire':'elbow',rotation:y===1?2:y===3?3:1}:{part:['pipes','water'].includes(c.active)?'straight':c.active==='power'?'wire':'block',rotation:0}):placed||hint||{part:'empty',rotation:0},img=tileImage(cell.part,cell.rotation);ctx.globalAlpha=!fixed&&!placed&&hint?0.45:1;if(img.complete&&img.naturalWidth)ctx.drawImage(img,120+x*60,180+y*60,60,60);ctx.globalAlpha=1;}ctx.fillStyle='#eef4df';ctx.font='17px system-ui';if(c.active==='power'){ctx.fillStyle=constructionPower(c)?'#f3ce6e':'#9cafb2';ctx.beginPath();ctx.arc(810,330,20,0,Math.PI*2);ctx.fill();ctx.fillStyle='#eff8f5';ctx.font='bold 23px system-ui';ctx.fillText('+',141,277);ctx.fillText('−',141,397);}if(c.active==='water'){const shut=c.boards.water[30]?.part==='valve'&&c.boards.water[30].rotation%2===1;ctx.fillStyle=shut?'#8c9c9e':'#71bfd6';ctx.beginPath();ctx.arc(810,330,17,0,Math.PI*2);ctx.fill();ctx.fillStyle='#eef4df';ctx.font='17px system-ui';ctx.fillText(shut?'Valve closed: model flow stopped.':'Valve open: model water can flow.',120,520);}ctx.fillText('Support and connection model • Test, change and repeat • No parts lost',35,555);}
function drawOrbit(){const phase=state.construction.phase||0;rect(0,0,1000,600,'#102b40');ctx.fillStyle='#eff8f5';ctx.font='bold 23px system-ui';ctx.fillText('MY SOLAR SYSTEM / TRAINING ORBIT PREVIEW',35,65);for(let i=0;i<50;i++)rect((i*127)%1000,170+(i*83)%390,2,2,'#a9c7d5');for(let i=0;i<3;i++){ctx.strokeStyle='#496479';ctx.beginPath();ctx.ellipse(510,340,100+i*65,50+i*35,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle=['#93c5b0','#82b5d9','#cc9c7f'][i];ctx.beginPath();ctx.arc(510+Math.cos(phase/(i+1)+i)* (100+i*65),340+Math.sin(phase/(i+1)+i)*(50+i*35),13+i*3,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#f3ce6e';ctx.beginPath();ctx.arc(510,340,32,0,Math.PI*2);ctx.fill();rect(100,470,180,35,'#9ab6bc');rect(80,450,45,70,'#406a8b');rect(260,450,45,70,'#406a8b');ctx.fillStyle='#eff8f5';ctx.font='17px system-ui';ctx.fillText('Station viewpoint • planets orbit a star • not to scale',100,555);}
function setDigLevel(level){state.excavation.level=level;state.excavation.path=[];state.excavation.target=null;state.x=180;state.y=180;state.path=[];renderTargets();persist();announce(level?'Deep cavern observation area.':'Upper excavation site.');}
function selectDigPoint(x,y,target=null){if(state.paused)return;const cell=digCell(x,y);if(digBlocked(...cell,state.excavation.level)){showDigLesson('magma');return}state.path=[];state.pending=null;state.ring={x:cell[0]*40+20,y:cell[1]*40+20};beginDig(state.excavation,[state.x,state.y],[x,y],target);announce(activeAstronautIndex()===3?'Aiden is using his heavy digging rig.':'Digging automatically. PIP helps with hard formations.');}
function showDigLesson(page){const v=digView(state.excavation,page,activeAstronautIndex());open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.innerHTML=digArt(v.art,state.excavation);art.className='farm-art';const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);const buttons=document.createElement('div');buttons.className='farm-choices';content.append(buttons);for(const a of v.actions)button(a.label,()=>{if(a.type==='reset'){state.excavation.cleared[state.excavation.level]=[];setDigLevel(state.excavation.level);close();}else if(a.type==='tool'){state.excavation.tool=a.value;persist();announce(a.label+' fitted.');close()}else if(a.type==='hints'){state.excavation.hints=true;renderTargets();persist();close()}else{state.excavation[a.type]=1-(state.excavation[a.type]||0);showDigLesson(page)}},buttons);button('🔊 Listen',()=>readJournal(v.text));paragraph('Supported training tunnels and cutaway models. Not to scale.');}
function showEngineering(project,page=0){const v=designView(project,state.discoveries,state.designs[project]);open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const a=document.createElement('div');a.className='farm-art';a.innerHTML=engineeringArt(project);const p=document.createElement('p');p.textContent=v.text;info.append(a,p);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const f of v.samples.slice(page*3,page*3+3))button((v.selected===f.id?'✓ ':'')+f.icon+' Use '+f.name,()=>{state.designs[project]=f.id;persist();showEngineering(project,page)},choices);if(!v.samples.length)button('⛏️ Find samples',()=>{close();select(objects.find(o=>o.id==='grounds-dig'))},choices);if(v.selected)button('🌱 Install on farm',()=>{state.farm.upgrades[project]=v.selected;persist();close();select(objects.find(o=>o.id===designFarmTarget(project)))},choices);if(page>0)button('← Previous',()=>showEngineering(project,page-1),choices);if(v.samples.length>(page+1)*3)button('Next →',()=>showEngineering(project,page+1),choices);button('🔊 Listen',()=>readJournal(v.text));paragraph('Reusable samples. No materials are spent. Selected: '+(v.selected||'none yet'));}
function updateDig(dt){const r=tickDig(state.excavation,[state.x,state.y],dt,activeAstronautIndex());[state.x,state.y]=r.position;if(r.changed){persist();renderTargets();}const arrived=objects.find(o=>o.id===r.arrived);if(r.found&&!state.discoveries.has(r.found)&&arrived?.find!==r.found)discover(digFinds.find(f=>f.id===r.found));if(arrived)interact(arrived);}
function drawDig(){rect(0,0,1000,600,'#203440');ctx.fillStyle='#eff3df';ctx.font='bold 21px system-ui';ctx.fillText(state.excavation.level?'DEEP CAVERNS • observe gently':'DIG SITE • tap ground to excavate',35,75);for(let y=4;y<=12;y++)for(let x=1;x<=23;x++){const lava=digBlocked(x,y,state.excavation.level),solid=digSolid(state.excavation,x,y);rect(x*40,y*40,39,39,lava?'#e79856':solid?(digHard(x,y)?'#66616e':y<=6?'#b59a73':y<=8?'#9c7c68':'#77717b'):'#283f4b');if(!solid&&!lava&&state.excavation.cleared[state.excavation.level].includes(x+','+y)){rect(x*40+8,y*40+30,24,3,'#b8a47a');rect(x*40+8,y*40+8,3,25,'#b8a47a');rect(x*40+29,y*40+8,3,25,'#b8a47a');}}ctx.fillStyle='#eef4df';ctx.font='16px system-ui';ctx.fillText('Automatic excavation • support lifts • PIP help • no failure states',40,560);}
const yardImages=new Map();function yardMachineArt(kind,x,y){const key=kind+'-'+state.construction[kind];if(!yardImages.has(key)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(constructionArt(key));yardImages.set(key,img)}const img=yardImages.get(key);if(img.complete&&img.naturalWidth)ctx.drawImage(img,x,y,160,100);}
function drawEngineering(){rect(0,0,1000,600,'#ceded4');rect(0,0,1000,100,'#203f4d');ctx.fillStyle='#eff3df';ctx.font='bold 24px system-ui';ctx.fillText('ENGINEERING & CONSTRUCTION YARD',35,60);yardMachineArt('printer',100,110);yardMachineArt('crane',380,110);yardMachineArt('robot',760,110);for(const [x,y,w]of [[100,330,160],[340,330,160],[760,330,160]])rect(x,y,w,90,'#aabfb2');rect(40,485,920,20,'#a18c69');for(const [x,y]of [[300,240],[650,240],[650,430]]){rect(x-100,y-60,200,110,'#9ab8b2');rect(x-80,y-40,160,70,'#e8edd9');}}
function showFarm(route='home',message=''){if(route==='machines'){showMachines();return;}const v=farmView(state.farm,route);open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=farmArt(farmArtKey(state.farm,route));art.setAttribute('role','img');art.setAttribute('aria-label',v.visual);const text=document.createElement('p');text.textContent=v.body;info.append(art,text);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const a of v.actions){const b=button(a.label,()=>{const result=farmAction(state.farm,a.action);state.farm=result.farm;persist();renderTargets();if(result.travel){close();select(objects.find(o=>o.id===result.travel))}else{chime();showFarm(result.route,result.message)}},choices);b.dataset.farmAction=a.action.type;if(a.action.id)b.dataset.plant=a.action.id;}const footer=document.createElement('div');footer.className='journal-controls';content.append(footer);button('🔊 Listen',()=>readJournal(v.title+'. '+v.body),footer);button('🗺️ Explore farm',()=>{close();if(state.zone!=='farm')select(objects.find(o=>o.id==='farm-garden'))},footer);paragraph(message||'Simple science models. Pictures are not to scale.','farm-message');speak(message||v.title+'. '+v.body);}
function journalEntries(section){return getJournalEntries(section,state.discoveries,state.visited,objects,materials,state.farm,state.construction,state.aquatic,state.chapter,state.elevator,state.machines,state.tech,state.rocketLab,state.expeditions,state.trailMachines,state.myWorlds)}
function readJournal(message){voice(message,true)}
function journalHome(){open('My Journal');panel.classList.add('journal-panel');paragraph('My stories. My discoveries. My adventures.','journal-intro');const grid=document.createElement('div');grid.className='journal-grid';content.append(grid);for(const section of journalSections){const b=button('',()=>journalPage(section.id),grid);b.dataset.section=section.id;const picture=document.createElement('span');picture.className='journal-icon';picture.textContent=section.icon;picture.setAttribute('aria-hidden','true');const title=document.createElement('span');title.textContent=section.title;b.append(picture,title);}button('🔊 Listen',()=>readJournal('My journal. Choose what I did, what I discovered, my adventures, my experiments, or my minerals.'));}
function journalPage(id,page=0){const section=journalSections.find(s=>s.id===id),entries=journalEntries(id);open(section.title);panel.classList.add('journal-panel');paragraph(section.intro,'journal-intro');const chunk=entries.slice(page*4,page*4+4);if(!entries.length){paragraph(section.icon,'illustration');paragraph(section.empty,'journal-empty');button('📍 Explore',()=>{close();select(objects.find(o=>o.id===section.target))});}const grid=document.createElement('div');grid.className='journal-grid journal-entries';content.append(grid);for(const entry of chunk){const b=button(entry.icon+' '+entry.title,()=>journalDetail(entry,id,page),grid);b.dataset.entry=entry.id;}const controls=document.createElement('div');controls.className='journal-controls';content.append(controls);button('← My Journal',journalHome,controls);if(page>0)button('← Previous',()=>journalPage(id,page-1),controls);if(entries.length>(page+1)*4)button('Next →',()=>journalPage(id,page+1),controls);button('🔊 Listen',()=>readJournal(section.title+'. '+(entries.length?chunk.map(e=>e.summary).join(' '):section.empty)),controls);}
function journalDetail(entry,section,page){open(entry.title);panel.classList.add('journal-panel');paragraph(entry.icon,'illustration');paragraph(entry.summary,'journal-intro');paragraph(entry.fact,'journal-fact');const controls=document.createElement('div');controls.className='journal-controls';content.append(controls);button('🔊 Listen',()=>readJournal(entry.summary+' '+entry.fact),controls);button('↻ Do It Again',()=>{close();if(entry.myWorldId){startMyWorldTrip(entry.myWorldId);return;}if(entry.expeditionMode){enterExpedition(entry.expeditionMode,entry.expeditionFocus);if(entry.trailPlacementId)showTrailMachines('placed:'+entry.trailPlacementId);return;}if(entry.rocketSky!==undefined){state.rocketLab.sky=entry.rocketSky;persist();}if(entry.machineId){showMachines('model:'+entry.machineId);return;}if(entry.elevatorDeck!==undefined){state.elevator.deck=entry.elevatorDeck;changeZone('elevator');showElevator('system');return;}select(objects.find(o=>o.id===entry.target))},controls);button('← '+journalSections.find(s=>s.id===section).title,()=>journalPage(section,page),controls);}
$('#journal').onclick=journalHome;
function crewMenu(onSelect=null){open('Choose your J.A.C.C. crew');panel.classList.add('crew-panel');paragraph('One tap selects your astronaut. Everyone can explore every activity.');const grid=document.createElement('div');grid.className='crew-grid';content.append(grid);for(const r of roster){const selected=!activeCustomJacc(state.jaccBuilder)&&characters.active[0]===r[0];const b=button('',()=>{state.jaccBuilder.activeId=null;state.suit.overlay=null;characters.select(r[0]);persist();updateCrew();close();announce(r[0]+' selected. '+r[2]);speak(r[0]+'. '+r[2]);if(typeof onSelect==='function')onSelect();},grid);b.className='crew-card';b.dataset.badge=String(roster.indexOf(r)+1);b.setAttribute('aria-label',r[0]+', '+crewDescription(r[0])+', '+r[1]+' suit. '+r[2]);b.setAttribute('aria-pressed',String(selected));const icon=document.createElement('span');icon.className='crew-portrait';icon.style.setProperty('--suit',suitColors[r[1]]);icon.setAttribute('aria-hidden','true');const name=document.createElement('strong');name.textContent=r[0];const detail=document.createElement('small');detail.textContent=crewDescription(r[0])+' • '+r[1]+' • '+r[2];const badge=document.createElement('span');badge.textContent=selected?'✓ Selected':'Select';b.append(icon,name,detail,badge);}button('🧑‍🚀 Build my J.A.C.C.',()=>showJaccBuilder('home',onSelect));button('📚 My J.A.C.C.s',()=>showJaccBuilder('library:0',onSelect));paragraph('Temporary suit-color placeholders. Approved character artwork will replace these.');}
function suitMenu(){if(state.expeditions.active){showExpedition('gear');return}if(activeCustomJacc(state.jaccBuilder)){customSuitMenu();return}open('Astronaut suit powers');const name=activeAstronautName(),powers=suitPowers[name]||[];paragraph(name+' • '+crewDescription(name));if(!powers.length)paragraph('This suit’s specialist tools are still being developed. Everyone can explore every activity.');for(const p of powers)button(p.icon+' '+p.name,()=>showSuitPower(p.id));button('◎ Clear suit overlay',()=>{state.suit.overlay=null;persist();close();announce('Ready to explore.');});button('👩‍🚀 Choose astronaut',crewMenu);}
function showSuitPower(id,step=0,target=state.last){const v=suitPowerView(activePowerOwner(id),id,step,{zone:state.zone,target,farm:state.farm,position:[state.x,state.y]});if(!v)return;open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=suitArt(v.art);const p=document.createElement('p');p.textContent=v.heading+'. '+v.text;info.append(art,p);content.append(info);button('✨ Reveal in world',()=>{state.suit=activateSuit(state.suit,activePowerOwner(id),id);persist();close();announce(v.title+' active. Tap a highlighted place to investigate.');});button('▶ Next / repeat',()=>showSuitPower(id,v.step+1,v.target));if(v.travel)button('🏗️ Try this plan',()=>{state.suit.overlay=null;persist();close();select(objects.find(o=>o.id===v.travel));});if(v.target)button('👆 Explore this place',()=>{state.suit.overlay=null;persist();close();select(objects.find(o=>o.id===v.target));});button('🔊 Listen',()=>readJournal(v.heading+'. '+v.text));button('← Suit powers',suitMenu);}
const suitButton=document.createElement('button');suitButton.id='suit';suitButton.setAttribute('aria-label','Astronaut suit powers');suitButton.innerHTML='✨<span>Suit</span>';suitButton.onclick=suitMenu;document.querySelector('nav').append(suitButton);
const suitOverlayImages=new Map();function drawSuitOverlay(){const power=suitPowerFor(activePowerOwner(state.suit.overlay),state.suit.overlay);if(!power)return;const cam=spaceCamera(state.zone,[state.x,state.y]),q=cam.map(v=>Math.floor(v/40)*40),key=power.id+'-'+state.zone+'-'+state.aquatic.habitat+'-'+state.excavation.level+'-'+q.join(',');if(!suitOverlayImages.has(key)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(suitOverlay(power,state.zone,state.aquatic.habitat,state.excavation.level,q));suitOverlayImages.set(key,img);if(suitOverlayImages.size>3)suitOverlayImages.delete(suitOverlayImages.keys().next().value)}const img=suitOverlayImages.get(key);if(img.complete&&img.naturalWidth)ctx.drawImage(img,q[0]-cam[0],q[1]-cam[1],1000,600);}
function updateCrew(){document.querySelector('#active-crew').textContent=activeAstronautName()+' • '+(activeCustomJacc(state.jaccBuilder)?'My custom J.A.C.C.':characters.active[1]+' suit');$('#crew').setAttribute('aria-label','Choose astronaut. Current: '+activeAstronautName());}
$('#crew').onclick=crewMenu;updateCrew();
function pipHelp(){if(state.trailMachines.roomOpen){showRoomMenu('help');return;}if(state.myWorlds.active){showMyWorld('help');return;}if(state.expeditions.active){showExpedition('mission');return}if(state.zone==='rocketlab'){showRocketLab('help');return}if(['engineering','machineyard'].includes(state.zone)||['hq','flight'].includes(state.zone)&&['hq-elon','flight-elon'].includes(state.last)){showConstruction('pip-help');return}if(['coding','robotics'].includes(state.zone)){const last=objects.find(o=>o.id===state.last&&o.zone===state.zone&&o.kind==='tech');showTech('pip-help:'+(last?.page|| (state.zone==='coding'?'home':'build')));return}open('PIP • Your exploration helper');paragraph('🤖 → 👆 → ⛏️','illustration');button('✨ Show places',()=>{close();if(state.zone==='dig'){state.excavation.hints=true;renderTargets();}document.querySelectorAll('.target').forEach(b=>b.classList.add('hint'));announce('The bright pictures are places you can explore.');});button(state.zone==='aquatic'?'🏊 Show me a swim':'▶ Show me a dig',()=>{close();select(state.zone==='aquatic'?activeObjects().find(o=>o.life):objects.find(o=>o.id==='dig'))});button('↩ Previous activity',()=>{close();select(objects.find(o=>o.id===state.last)||objects.find(o=>o.id===zones[state.zone].home))});button('🔊 Repeat guidance',()=>{announce('Tap a picture. Your astronaut walks there and explores. Tap the pickaxe to dig.');speak('Tap a picture. Your astronaut walks there and explores. Tap the pickaxe to dig.')});button('🏠 Return home',()=>{close();select(objects.find(o=>o.id===zones[state.zone].home))});button('🛠 Build PIP',pipWorkshop);button('🔎 Analyze a discovery',pipDiscoveries)};
$('#pip').onclick=pipHelp;
function pipWorkshop(){open('PIP Workshop');panel.classList.add('pip-panel');mountPipWorkshop({root:content,config:state.pip,crewIndex:()=>activeCustomJacc(state.jaccBuilder)?jaccMatchIndex(activeCustomJacc(state.jaccBuilder),roster):activeAstronautIndex(),onChange:c=>{state.pip=c;persist();chime()},onDone:()=>{close();announce('PIP is ready to explore with '+activeAstronautName()+'.')},onTryTool:()=>pipToolLessons[state.pip.tool]?showPipTool(state.pip.tool):pipDiscoveries(),onAnalyze:pipDiscoveries,onHelp:pipHelp,onSpeak:readJournal});}
function showPipTool(tool,step=0){const v=pipToolView(tool,step);open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=pipToolArt(v.art);const p=document.createElement('p');p.textContent=v.heading+'. '+v.text;info.append(art,p);content.append(info);button('▶ Next / repeat',()=>showPipTool(v.tool,v.step+1));button('🔊 Listen',()=>readJournal(v.heading+'. '+v.text));button('🛠 PIP Workshop',pipWorkshop);}
function pipDiscoveries(){open('Ask PIP');paragraph('Choose something I discovered.');const found=materials.filter(m=>state.discoveries.has(m.id));if(!found.length){paragraph('Dig to find our first sample.');button('⛏️ Go digging',()=>{close();select(objects.find(o=>o.id==='dig'))})}for(const m of found)button(m.icon+' '+m.name,()=>showPipAnalysis(m.id));button('← PIP Workshop',pipWorkshop);}
