function drawWildlife(generated){if(state.construction.active||state.construction.orbit)return;const poses=generated?expeditionWildlife(state.expeditions,state.wildlifeTime||0):landscapeWildlife(state.zone,spaceCamera(state.zone,[state.x,state.y]),state.wildlifeTime||0,{habitat:state.aquatic.habitat,level:state.excavation.level,clearCells:state.zone==='dig'?state.excavation.cleared[state.excavation.level]:state.openWorld.cleared});ctx.save();ctx.beginPath();ctx.rect(0,95,1000,425);ctx.clip();for(const o of poses)drawWildlifeSprite(o);ctx.restore();}

function showTrailMachines(route='home',message=''){const v=trailMachineView(state.expeditions,state.trailMachines,state.machines,route);open(v.title);panel.classList.add('farm-panel');paragraph(v.text,'journal-intro');if(v.design){const art=document.createElement('div');art.className='farm-art machine-art';art.innerHTML=machineSvg(v.design,{background:false});content.append(art);}const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const a of v.actions)button(a.label,()=>runTrailMachine(a),choices);button('🔊 Listen',()=>readJournal(v.title+'. '+v.text+(message?' '+message:'')),choices);if(message)paragraph(message,'farm-message');}
function runTrailMachine(a){if(a.type==='room'){openHabitatRoom(a.id);return;}if(a.type==='rooms'){showRoomMenu('library:0');return;}if(state.paused&&!['page','resume','pack','workshop'].includes(a.type)){announce('Tap Resume to use your machine.');return;}const r=trailMachineAction(state.expeditions,state.trailMachines,state.machines,a);if(r.enter)enterExpedition(r.enter,r.effect?.focus);if(r.effect&&!r.effect.focus)applyExpeditionEffect(r.effect);if(r.pause!==null){state.paused=r.pause;$('#pause').innerHTML=r.pause?'▶ <span>Resume</span>':'Ⅱ <span>Pause</span>';}persist();if(r.workshop){showMachines(r.workshop);return;}if(r.route===null)close();else showTrailMachines(r.route,r.message);if(r.message)announce(r.message);}
