function runMyWorldAction(a){if(state.myWorlds.travel&&['machines','plant'].includes(a.type)){announce('Choose Arrive now or Cancel trip first.');return;}if(a.type==='machines'){showTrailMachines();return;}if(a.type==='plant'){close();runExpeditionAction({type:'goal'});return;}if(a.type==='close'){close();return;}const r=myWorldAction(state,a);persist();if(r.travel){startMyWorldTrip(r.travel);return;}showMyWorld(r.route);}
function startMyWorldTrip(id){state.trailMachines.roomOpen=null;close();const w=state.expeditions.active?state.expeditions.worlds[state.expeditions.active]:null,cam=w?expeditionCamera(w,state.expeditions.active):null;const start=w?{x:w.x-cam.x,y:w.y-cam.y+95}:{x:state.x,y:state.y};if(!beginMyWorldTravel(state,id,start))return;myTripCaption='';state.path=[];state.pending=null;state.action=null;state.construction.active=null;state.construction.orbit=false;state.started=true;state.paused=false;$('#begin').hidden=true;$('#first-visit-start').hidden=true;$('#pause').innerHTML='Ⅱ <span>Pause</span>';persist();if(state.settings.reduced||!state.settings.effects)skipMyWorldTrip();}
function skipMyWorldTrip(){state.paused=false;const r=tickMyWorldTravel(state,0,{skip:true});if(r)finishMyWorldArrival(r);}
function finishMyWorldArrival(r){myTripRoot.hidden=true;myTripCaption='';if(r.hub){state.expeditions.active=null;changeZone('grounds');}else{state.started=true;state.paused=false;expBandKey='';renderTargets();announce('Welcome to '+state.expeditions.colony.name+'. Your garden and creations are here.');if(state.firstVisit.mode==='guided')showMyWorld('help');}$('#pause').innerHTML='Ⅱ <span>Pause</span>';persist();}
