function drawMyWorldTrip(){roomRoot.hidden=true;setMyTripControls(true);const p=myWorldTravelPose(state.myWorlds);if(!p)return;expRoot.hidden=true;$('#targets').replaceChildren();myTripRoot.hidden=false;ctx=sceneCtx;ctx.clearRect(0,0,1000,600);actorCtx.clearRect(0,0,1000,600);const bg=myTripImage('bg-'+p.background+'-'+p.space,myWorldBackdropSvg(p.background,p.space));if(bg.complete&&bg.naturalWidth)ctx.drawImage(bg,0,0,1000,600);const custom=activeCustomJacc(state.jaccBuilder),color=custom?jaccPaints[custom.colors.armor]:suitColors[characters.active[1]],astronaut=myTripImage('avatar-'+(custom?JSON.stringify(custom):color),custom?jaccSvg({...custom,parts:{...custom.parts,back:'both'}}):myWorldAstronautSvg(color)),pip=myTripImage('pip-'+JSON.stringify(state.pip),pipSvg({...state.pip,travel:'hover'})),rocket=myTripImage('rocket-'+color,myWorldRocketSvg(color));for(const [img,pose,w,h]of [[astronaut,p.astronaut,60,80],[pip,p.pip,70,70],[rocket,p.rocket,100,160]]){if(!pose.scale||!img.complete||!img.naturalWidth)continue;ctx.save();ctx.translate(pose.x,pose.y);ctx.rotate((pose.angle||0)*Math.PI/180);ctx.drawImage(img,-w*pose.scale/2,-h*pose.scale/2,w*pose.scale,h*pose.scale);ctx.restore();}if(myTripCaption!==p.stage){myTripCaption=p.stage;announce(p.caption);persist();}}

function setMyTripControls(traveling){for(const id of ['pip','crew','journal','suit','visit','places']){const b=document.getElementById(id);if(b)b.disabled=traveling;}}

function habitatCtx(){const minerals=materials.filter(m=>state.discoveries.has(m.id));const discoveries=objects.filter(o=>o.kind!=='portal'&&state.visited.has(o.id)).map(o=>({id:o.id,name:o.name,icon:o.icon})).concat(state.aquatic.observed.map(id=>{const a=aquaticLife.find(o=>o.id===id);return a?{id,name:a.name,icon:a.icon}:null}).filter(Boolean));return {minerals,plants:farmPlants.filter(p=>state.farm.seeds.includes(p.id)),discoveries:discoveries.filter((o,i,a)=>a.findIndex(x=>x.id===o.id)===i).slice(0,80)};}
function openHabitatRoom(id){if(ensureRoom(state.trailMachines,id)){state.path=[];state.pending=null;state.action=null;close();state.paused=false;$('#pause').innerHTML='Ⅱ <span>Pause</span>';persist();announce('Welcome to your room. Tap furniture, then a big spot. The door leads outside.');}else showRoomMenu('library:0');}
function showRoomMenu(route){if(route==='close'){close();return;}const v=roomView(state.trailMachines,route,habitatCtx());open(v.title);panel.classList.add('farm-panel');paragraph(v.text,'journal-intro');const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const a of v.actions)button(a.label,()=>runRoomAction(a),choices);if(v.actions.length<6)button('🔊 Listen',()=>readJournal(v.title+'. '+v.text),choices);}
function runRoomAction(a){if(a.type==='page'){showRoomMenu(a.route);return;}if(a.type==='open'){openHabitatRoom(a.id);return;}if(a.type==='machines'){showTrailMachines();return;}if(a.type==='journal'){journalHome();return;}const r=roomAction(state.trailMachines,a,habitatCtx());if(a.type==='exit')renderTargets();if(r.pause!==null){state.paused=r.pause;$('#pause').innerHTML=r.pause?'▶ <span>Resume</span>':'Ⅱ <span>Pause</span>';}persist();if(r.effect==='journal'){journalHome();return;}if(r.route===null)close();else showRoomMenu(r.route);if(r.message)announce(r.message);}
const roomRoot=document.createElement('div');roomRoot.id='habitat-room';roomRoot.hidden=true;$('#stage').append(roomRoot);const roomSlotButtons=roomSpots.map((spot,slot)=>{const b=document.createElement('button');b.className='room-spot';b.dataset.roomSlot=slot;b.style.left=spot.x/10+'%';b.style.top=spot.y/6+'%';b.onclick=()=>runRoomAction({type:'spot',slot});roomRoot.append(b);return b;});const roomFooter=document.createElement('div');roomFooter.className='room-footer';roomRoot.append(roomFooter);for(const [label,action]of [['🛏 Furniture',{type:'page',route:'furniture:0'}],['🎨 Colors',{type:'page',route:'colors'}],['💎 Displays',{type:'page',route:'displays'}],['↶ Undo',{type:'undo'}],['🚪 Exit',{type:'exit'}]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>runRoomAction(action);roomFooter.append(b);}const roomDoor=document.createElement('button');roomDoor.className='room-door';roomDoor.textContent='🚪 Exit';roomDoor.onclick=()=>runRoomAction({type:'exit'});roomRoot.append(roomDoor);const roomImages=new Map();
function roomImage(key,svg){if(!roomImages.has(key)){const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);roomImages.set(key,img);}return roomImages.get(key);}
function drawHabitatRoom(){const s=state.trailMachines,r=s.rooms[s.roomOpen];if(!r){s.roomOpen=null;return;}roomRoot.hidden=false;expRoot.hidden=true;$('#targets').replaceChildren();ctx=sceneCtx;ctx.clearRect(0,0,1000,600);actorCtx.clearRect(0,0,1000,600);const theme=state.settings.highContrast?'contrast':r.theme,bg=roomImage('bg-'+theme,roomBackdrop(theme));if(bg.complete&&bg.naturalWidth)ctx.drawImage(bg,0,0,1000,600);for(let i=0;i<6;i++){const spot=roomSpots[i],token=r.slots[i],b=roomSlotButtons[i];b.textContent=s.roomChoice?'＋ Place here':roomName(token,habitatCtx());b.classList.toggle('room-empty',!token);b.setAttribute('aria-label',spot.name+': '+(s.roomChoice?'Place '+roomName(s.roomChoice,habitatCtx()):roomName(token,habitatCtx())));if(token){const img=roomImage('item-'+token,roomItemArt(token));if(img.complete&&img.naturalWidth)ctx.drawImage(img,spot.x-90,spot.y-55,180,105);}}drawPipBuddy(55,390);const d=activeCustomJacc(state.jaccBuilder),img=roomImage('avatar-'+(d?JSON.stringify(d):characters.active[1]),d?jaccSvg(d):myWorldAstronautSvg(suitColors[characters.active[1]]));if(img.complete&&img.naturalWidth)ctx.drawImage(img,60,450,48,64);ctx.fillStyle='#fffbed';ctx.fillRect(20,102,810,55);ctx.fillStyle='#17384a';ctx.font='bold 21px system-ui';ctx.fillText(state.paused?'Resting · tap PIP for Resume':s.roomChoice?'Tap a big spot to place '+roomName(s.roomChoice,habitatCtx()):'My habitat · make yourself at home',35,136);}
const professorButton=document.createElement('button');professorButton.id='professor-guide';professorButton.onclick=()=>showProfessor();$('#stage').append(professorButton);let professorGuideId='';
function updateProfessorGuide(){professorButton.hidden=!!(state.myWorlds.travel||state.trailMachines.roomOpen||state.expeditions.active||state.construction.active||state.construction.orbit);const id=zoneProfessor(state.zone,state.expeditions);if(id!==professorGuideId){professorGuideId=id;professorButton.replaceChildren();const image=document.createElement('img');image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(professorPortrait(id));image.alt='';professorButton.append(image,document.createTextNode(professors[id].name));professorButton.setAttribute('aria-label','Talk to '+professors[id].name+' about '+professors[id].specialty);}}
function showProfessor(id=zoneProfessor(state.zone,state.expeditions),route='home'){if(route==='repeat'){const v=professorView(id,'help');readJournal(v.text);return;}const v=professorView(id,route);open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=professorPortrait(id);const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const a of v.actions)button(a.label,()=>a.type==='professor'?showProfessor(a.id):a.type==='page'?showProfessor(id,a.route):runProfessorActivity(a.activity),choices);button('🔊 Listen',()=>readJournal(v.title+'. '+v.text),choices);}
function runProfessorActivity(a){if(a.system==='farm')showFarm(a.page);if(a.system==='dig')showDigLesson(a.page);if(a.system==='aquatic')showAquatic(a.page);if(a.system==='magnet')showMagnetLab(a.page);if(a.system==='tech')showTech(a.page);if(a.system==='construction')showConstruction(a.page);if(a.system==='rocket')showRocketLab(a.page);if(a.system==='analysis')showPipAnalysis(a.page);if(a.system==='piptool')showPipTool(a.page);}
